package org.rsmod.content.skills.sailing

/**
 * Sailing tier 0 data generated by `tools/skills/sailing_to_tsv.py` from the rev 243 dbrow dump
 * (port_task rows: ports, cargo crates) and the OSRS Wiki (courier xp, charting levels).
 */
internal object SailingData {
    /** A port: its sailing_dock dbrow and the notice board / ledger table locs placed there. */
    class Port(val key: String, val dock: String, val board: String?, val ledger: String?)

    class Courier(
        val taskId: Int,
        val dbrow: String,
        val level: Int,
        val xp: Double,
        /** Port whose notice board offers the task. */
        val board: String,
        /** Port whose ledger table hands out the cargo. */
        val cargoPort: String,
        /** Port whose ledger table takes the delivery. */
        val destination: String,
        val crate: String,
        val count: Int,
        val name: String,
    )

    /** A generic "Chart" loc and the varbit that records it. */
    class ChartLoc(val loc: String, val varbit: String)

    /** A Wiki sea charting row (level by position; locs are matched to the nearest row). */
    class ChartRow(val x: Int, val z: Int, val level: Int, val spyglass: Boolean)

    val ports: List<Port> by lazy { rows("port").map { Port(it[1], it[2], it[3].orNull(), it[4].orNull()) } }

    val couriers: List<Courier> by lazy {
        rows("courier").map {
            Courier(
                taskId = it[1].toInt(),
                dbrow = it[2],
                level = it[3].toInt(),
                xp = it[4].toDouble(),
                board = it[5],
                cargoPort = it[6],
                destination = it[7],
                crate = it[8],
                count = it[9].toInt(),
                name = it.getOrElse(10) { "Courier task" },
            )
        }
    }

    val chartLocs: List<ChartLoc> by lazy { rows("chartloc").map { ChartLoc(it[1], it[2]) } }

    val chartRows: List<ChartRow> by lazy {
        rows("chart").map { ChartRow(it[1].toInt(), it[2].toInt(), it[3].toInt(), it[4] == "spyglass") }
    }

    private fun String.orNull(): String? = takeIf { it != "-" }

    private val lines: List<List<String>> by lazy {
        val input =
            SailingData::class.java.getResourceAsStream("sailing.tsv")
                ?: error("Sailing resource not found: sailing.tsv")
        input.bufferedReader().use { it.readLines() }
            .map { it.trimEnd() }
            .filter { it.isNotBlank() && !it.startsWith("#") }
            .map { it.split('\t') }
    }

    private fun rows(kind: String): List<List<String>> = lines.filter { it[0] == kind }
}
